CREATE TABLE "public"."availability" (
  "date"       date                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "player"     bigint                   NOT NULL,
  CONSTRAINT "player_availability_pkey" PRIMARY KEY (date, player)
);

ALTER TABLE "public"."availability"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."games" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "title"       text                     NOT NULL,
  "gm"          bigint                   NOT NULL,
  "description" text,
  "open"        boolean                  DEFAULT true,
  "guests"      boolean                  DEFAULT false,
  "min"         smallint                 DEFAULT '1'::smallint,
  "max"         smallint,
  CONSTRAINT "games_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."games"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."players" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "name"       text,
  "pfp_url"    text,
  "active"     boolean                  DEFAULT true,
  CONSTRAINT "players_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."players"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."playing" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "player"     bigint                   NOT NULL,
  "game"       bigint                   NOT NULL,
  "active"     boolean                  DEFAULT true,
  CONSTRAINT "playing_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."playing"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."availability"
  ADD CONSTRAINT "player_availability_player_fkey" FOREIGN KEY (player) REFERENCES public.players(id) ON DELETE CASCADE;

ALTER TABLE "public"."games"
  ADD CONSTRAINT "games_gm_fkey" FOREIGN KEY (gm) REFERENCES public.players(id);

